      if (lookahead == ',') ADVANCE(11);
      if (lookahead == '=') ADVANCE(10);
      if (lookahead == '@') ADVANCE(5);
      if (lookahead == '\\') ADVANCE(6);
      if (lookahead == '}') ADVANCE(19);
